 * @param rowIndex columnIndex columnId
 * @returns
 * @hidden N
*/
scwin.grd_mergeObjCorpList_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_mergeObjCorpList');
        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_mergeObjCorpList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; }
        if (typeof scwin.openInfoWin1 === 'function') { await scwin.openInfoWin1(); } else { console.error('[sdd] 행 동작 미정의: scwin.openInfoWin1 (열 ?)'); await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — scwin.openInfoWin1'); } return;
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_mergeObjCorpList.oncellclick' });
    }
};

